const items = $input.all();
const sessionId = $('Chat Trigger').first().json.sessionId;

const match = items.find(it => {
  const f = it.json.fields || it.json;
  return (f['Session_ID'] || '').toString().replace(/^=+/, '') === sessionId;});

if (!match) {
  return [{ json: {
    found: false,
    session_id: sessionId,
    user_name: 'Usuario nuevo',
    status: 'Nuevo',
    last_summary: '(sin historial previo)',
    intercambios: 0
  } }];
}

const f = match.json.fields || match.json;
return [{ json: {
  found: true,
  session_id: sessionId,
  user_name: f['Nombre_Usuario'] || 'Usuario',
   status: (f['Estado_del_Caso'] || '').toString().replace(/^=+/, '') || 'Sin estado registrado',
  last_summary: (f['Resumen_Consolidado'] || '').toString().replace(/^=+/, '') || '(sin resumen previo)',} }];

const text = ($input.first().json.text || $input.first().json.output || '').toString().trim().toUpperCase();
let categoria = 'HUMANO';
if (text.includes('LEADS')) categoria = 'LEADS';
else if (text.includes('EMAIL')) categoria = 'EMAIL';
return [{ json: { categoria } }];

